// Package ops implements the T15 operator console: channel and model master
// data. Pricing, groups, announcements, risk, users and configuration are a
// later segment; the only announcement write here is the draft generated by a
// model listing-state change.
//
// Three rules shape the package:
//
//   - Money is integer micro-credits / fen. Floating point is never used.
//   - An upstream key is sealed with internal/cryptobox before it reaches the
//     database. The plaintext exists only in the request variable and is never
//     written to a response, an audit row or a log line. Responses carry the
//     mask only.
//   - Every write is audited with before/after values inside the same
//     transaction, so an unlogged change cannot commit.
package ops

import (
	"context"
	"database/sql"
	"errors"
	"io"
	"net/http"
	"strconv"
	"strings"
	"time"

	"yunshu.dev/core/internal/apierr"
	"yunshu.dev/core/internal/control/audit"
	"yunshu.dev/core/internal/control/mw"
	"yunshu.dev/core/internal/cryptobox"
	"yunshu.dev/core/internal/jsonx"
	obslog "yunshu.dev/core/internal/obs/log"
	"yunshu.dev/core/internal/platform/clock"
)

// Service owns the operator master-data surface.
type Service struct {
	DB     *sql.DB
	Audit  *audit.Writer
	Now    clock.Clock
	Logger *obslog.Logger

	// PublishRoutes republishes cfg:snap:ROUTING. A channel weight or enabled
	// flag and a model listing state change all affect what the gateway may
	// route; without a publish the new value waits up to four minutes for the
	// timer. Nil is allowed in unit tests.
	PublishRoutes func(ctx context.Context) error

	// Box seals upstream keys. Nil means CHANNEL_KEY_KEK is absent: creating or
	// rotating a key answers 503 config_unavailable instead of storing
	// plaintext or an unopenable row.
	Box *cryptobox.Box
}

// New wires the service.
func New(db *sql.DB, auditWriter *audit.Writer, now clock.Clock, logger *obslog.Logger,
	publish func(ctx context.Context) error, box *cryptobox.Box) *Service {
	if now == nil {
		now = clock.Real{}
	}
	if auditWriter == nil {
		auditWriter = &audit.Writer{DB: db, Now: now}
	}
	return &Service{
		DB:            db,
		Audit:         auditWriter,
		Now:           now,
		Logger:        logger,
		PublishRoutes: publish,
		Box:           box,
	}
}

func (s *Service) now() time.Time { return s.Now.Now().UTC() }

func (s *Service) logError(ctx context.Context, msg string) {
	if s.Logger != nil {
		s.Logger.Error(ctx, msg, obslog.Fields{Stage: "ops", Status: http.StatusInternalServerError})
	}
}

func (s *Service) logWarn(ctx context.Context, msg string) {
	if s.Logger != nil {
		s.Logger.Warn(ctx, msg, obslog.Fields{Stage: "ops"})
	}
}

// decodeJSON is the bounded body reader for operator writes.
func decodeJSON(w http.ResponseWriter, r *http.Request, dst any) *apierr.APIError {
	r.Body = http.MaxBytesReader(w, r.Body, 256*1024)
	payload, err := io.ReadAll(r.Body)
	if err != nil || len(strings.TrimSpace(string(payload))) == 0 {
		return mw.InvalidField("body")
	}
	if err := jsonx.Unmarshal(payload, dst); err != nil {
		return mw.InvalidField("body")
	}
	return nil
}

// pathID reads a positive integer path value.
func pathID(r *http.Request, name string) (int64, *apierr.APIError) {
	raw := strings.TrimSpace(r.PathValue(name))
	id, err := strconv.ParseInt(raw, 10, 64)
	if err != nil || id <= 0 {
		return 0, mw.InvalidField(name)
	}
	return id, nil
}

// actor returns the session operator. Session middleware has already run; a
// missing session here is an internal wiring bug, answered as 401.
func actor(r *http.Request) (int64, string, *apierr.APIError) {
	sess, ok := mw.SessionFrom(r.Context())
	if !ok || sess == nil {
		return 0, "", mw.SessionMissing()
	}
	return sess.UID, sess.Role, nil
}

// insertAudit writes one row on the caller's transaction. Callers must pass a
// mask-only view: the upstream key plaintext and envelope never enter here.
func (s *Service) insertAudit(ctx context.Context, tx *sql.Tx, r *http.Request,
	module, action, targetType string, targetID int64, before, after any, reason string) error {
	beforeJSON, afterJSON, err := audit.MarshalBeforeAfter(before, after)
	if err != nil {
		return err
	}
	uid, role, apiErr := actor(r)
	if apiErr != nil {
		return errors.New("ops: audit requires a session")
	}
	return s.Audit.Insert(ctx, tx, audit.Entry{
		OperatorID:   uid,
		OperatorRole: role,
		OperatorIP:   audit.IPBytes(r),
		Module:       module,
		Action:       action,
		TargetType:   targetType,
		TargetID:     strconv.FormatInt(targetID, 10),
		Before:       beforeJSON,
		After:        afterJSON,
		// t_admin_audit_log.reason is varchar(255); truncation keeps a long
		// operator note from failing the whole write under strict mode.
		Reason: truncateRunes(reason, 255),
		Result: "OK",
	})
}

// publish republishes the routing snapshot after a committed change. A failure
// is not rolled back (the row is already committed) but the caller is told 503
// config_unavailable so the operator knows the gateway has not seen it yet.
func (s *Service) publish(ctx context.Context) *apierr.APIError {
	if s.PublishRoutes == nil {
		return nil
	}
	if err := s.PublishRoutes(ctx); err != nil {
		s.logError(ctx, "ops_route_publish_failed: "+err.Error())
		return apierr.New(apierr.CodeConfigUnavailable).WithCause(err)
	}
	return nil
}

// nullableTime converts sql.NullTime to the JSON shape.
func nullableTime(t sql.NullTime) *time.Time {
	if !t.Valid {
		return nil
	}
	v := t.Time.UTC()
	return &v
}
